1: /// Docker 安全隔离集成测试。
2: ///
3: /// 验证：NetworkMode=none 阻断网络、敏感路径不可访问。
4: mod common;
5: use common::{
6:     create_test_container, ensure_test_image, get_docker, is_e2e_enabled, wait_container,
7: };
8: 
9: /// 网络隔离测试：NetworkMode=none 下网络请求应失败
10: #[ignore]
11: #[serial_test::serial]
12: #[tokio::test]
13: async fn test_network_isolation() {
14:     if !is_e2e_enabled() {
15:         return;
16:     }
17: 
18:     let docker = get_docker().expect("连接 Docker 失败");
19:     ensure_test_image(&docker).await.expect("确保测试镜像失败");
20: 
21:     let code = "import urllib.request; urllib.request.urlopen('https://example.com', timeout=5)";
22:     let (container_id, work_dir) = create_test_container(
23:         &docker,
24:         "noj-judge-test-runner",
25:         &["python3", "-c", code],
26:         256,
27:         15000,
28:     )
29:     .await
30:     .expect("创建容器失败");
31: 
32:     let output = tokio::time::timeout(
33:         std::time::Duration::from_secs(30),
34:         wait_container(&docker, &container_id, 15000),
35:     )
36:     .await
37:     .expect("容器执行超时")
38:     .expect("等待容器失败");
39: 
40:     // 网络请求应被阻断，退出码非 0
41:     assert_ne!(output.exit_code, 0, "网络隔离测试：请求应失败但退出了码 0");
42:     let _ = std::fs::remove_dir_all(&work_dir);
43: }
44: 
45: /// 敏感路径不可访问测试。
46: ///
47: /// 验证容器内无法访问宿主机敏感路径。
48: /// 注意：/etc/passwd 和 /proc/* 在正常 Docker 容器中天然存在
49: ///（分别来自镜像和 /proc 挂载），不代表宿主机路径泄漏。
50: /// 此处仅检查确实不应存在的路径（Docker socket、宿主机数据目录等）。
51: #[ignore]
52: #[serial_test::serial]
53: #[tokio::test]
54: async fn test_container_no_sensitive_mounts() {
55:     if !is_e2e_enabled() {
56:         return;
57:     }
58: 
59:     let docker = get_docker().expect("连接 Docker 失败");
60:     ensure_test_image(&docker).await.expect("确保测试镜像失败");
61: 
62:     // 仅检查那些在正常容器中不应存在的敏感路径
63:     let code = r#"import os; paths=['/var/run/docker.sock','/host','/var/lib/docker']; [print(p) for p in paths if os.path.exists(p)]"#;
64:     let (container_id, work_dir) = create_test_container(
65:         &docker,
66:         "noj-judge-test-runner",
67:         &["python3", "-c", code],
68:         256,
69:         10000,
70:     )
71:     .await
72:     .expect("创建容器失败");
73: 
74:     let output = tokio::time::timeout(
75:         std::time::Duration::from_secs(30),
76:         wait_container(&docker, &container_id, 10000),
77:     )
78:     .await
79:     .expect("容器执行超时")
80:     .expect("等待容器失败");
81: 
82:     assert_eq!(output.exit_code, 0, "敏感路径检查应正常退出");
83:     assert!(
84:         output.stdout.trim().is_empty(),
85:         "不应发现宿主机敏感路径，但找到了: {}",
86:         output.stdout
87:     );
88:     let _ = std::fs::remove_dir_all(&work_dir);
89: }
